SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2005.YEAR, Станции2005.NUST, Станции2005.E, Станции2005.EOTP, Станции2005.EURT, Станции2005.EUST, Станции2005.Q, Станции2005.TURT, Станции2005.TUST, Станции2005.B, Станции2005.GAZ, Доп_угли2005.gazpp, Станции2005.MAZUT, Станции2005.TORF, Станции2005.SLAN, Станции2005.GTT, Станции2005.PROCH, Станции2005.UGOL, Станции2005.DON, Станции2005.PODM, Станции2005.PECH, Доп_угли2005.int, Доп_угли2005.vork, Станции2005.ARKT, Станции2005.KUZN, Станции2005.URAL, Доп_угли2005.sver, Доп_угли2005.chel, Доп_угли2005.kizel, Станции2005.BASHK, Станции2005.EKIB, Станции2005.KARAG, Станции2005.KAN, Доп_угли2005.nazar, Доп_угли2005.ibor, Доп_угли2005.berez, Доп_угли2005.per, Станции2005.IRKUT, Доп_угли2005.azey, Доп_угли2005.cher, Доп_угли2005.jer, Станции2005.HAK, Станции2005.TUV, Станции2005.BUR, Доп_угли2005.gusin, Доп_угли2005.tugn, Станции2005.CHIT, Доп_угли2005.har, Доп_угли2005.urt, Станции2005.[YAKUT] AS Выражение1, Станции2005.[AMUR] AS Выражение2, Станции2005.URG, Станции2005.PRIM, Станции2005.LUCH, Станции2005.MAG, Станции2005.SAH, Станции2005.USHUM, Станции2005.QOTR, Станции2005.SNK, Станции2005.EWTP, Станции2005.NT, Станции2005.OBOR, Станции2005.VED, Станции2005.OBL, Станции2005.DEP, Станции2005.OES, Станции2005.ER, Станции2005.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Станции2005.NTsum
FROM (((Станции2005 INNER JOIN Имена_станций ON Станции2005.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2005.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2005.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2005 ON (Станции2005.NUMB1120=Доп_угли2005.NUMB1120) AND (Станции2005.YEAR=Доп_угли2005.YEAR);
